from ortools.linear_solver import pywraplp
import json

def main():
    solver = pywraplp.Solver.CreateSolver("GLOP")
    if not solver:
        print("Could not create solver")
        return

    nodes = ["plant", "A", "B", "C", "D", "E", "F", "G", "H", "consumer"]
    intermediate_nodes = ["A", "B", "C", "D", "E", "F", "G", "H"]

    arcs = [
        ("plant", "A"), ("plant", "B"),
        ("A", "C"), ("A", "D"),
        ("B", "D"), ("B", "E"),
        ("C", "F"),
        ("D", "F"), ("D", "G"),
        ("E", "G"), ("E", "H"),
        ("F", "consumer"),
        ("G", "consumer"),
        ("H", "G"), ("H", "consumer")
    ]

    capacity = {
        ("plant", "A"): 10,
        ("plant", "B"): 8,
        ("A", "C"): 5,
        ("A", "D"): 7,
        ("B", "D"): 6,
        ("B", "E"): 9,
        ("C", "F"): 8,
        ("D", "F"): 4,
        ("D", "G"): 10,
        ("E", "G"): 7,
        ("E", "H"): 5,
        ("F", "consumer"): 12,
        ("G", "consumer"): 9,
        ("H", "G"): 6,
        ("H", "consumer"): 8
    }

    cost = {
        ("plant", "A"): 2,
        ("plant", "B"): 3,
        ("A", "C"): 1,
        ("A", "D"): 2,
        ("B", "D"): 4,
        ("B", "E"): 2,
        ("C", "F"): 3,
        ("D", "F"): 5,
        ("D", "G"): 1,
        ("E", "G"): 3,
        ("E", "H"): 2,
        ("F", "consumer"): 2,
        ("G", "consumer"): 4,
        ("H", "G"): 1,
        ("H", "consumer"): 3
    }

    flow = {}
    for arc in arcs:
        flow[arc] = solver.NumVar(0, capacity[arc], f"flow_{arc[0]}_{arc[1]}")

    total_power = solver.NumVar(0, solver.infinity(), "total_power")
    total_cost = solver.NumVar(0, solver.infinity(), "total_cost")

    for node in intermediate_nodes:
        incoming = []
        for arc in arcs:
            if arc[1] == node:
                incoming.append(flow[arc])

        outgoing = []
        for arc in arcs:
            if arc[0] == node:
                outgoing.append(flow[arc])

        if incoming and outgoing:
            solver.Add(solver.Sum(incoming) == solver.Sum(outgoing))

    consumer_inflows = []
    for arc in arcs:
        if arc[1] == "consumer":
            consumer_inflows.append(flow[arc])
    solver.Add(total_power == solver.Sum(consumer_inflows))

    cost_terms = []
    for arc in arcs:
        cost_terms.append(cost[arc] * flow[arc])
    solver.Add(total_cost == solver.Sum(cost_terms))

    solver.Maximize(total_power)
    status = solver.Solve()

    if status == pywraplp.Solver.OPTIMAL:
        max_power_value = total_power.solution_value()

        step1_flows = {}
        for arc in arcs:
            step1_flows[arc] = flow[arc].solution_value()

        solver2 = pywraplp.Solver.CreateSolver("GLOP")
        if not solver2:
            print("Could not create solver for step 2")
            return

        flow2 = {}
        for arc in arcs:
            flow2[arc] = solver2.NumVar(0, capacity[arc], f"flow2_{arc[0]}_{arc[1]}")

        total_power2 = solver2.NumVar(0, solver2.infinity(), "total_power2")
        total_cost2 = solver2.NumVar(0, solver2.infinity(), "total_cost2")

        for node in intermediate_nodes:
            incoming = []
            for arc in arcs:
                if arc[1] == node:
                    incoming.append(flow2[arc])

            outgoing = []
            for arc in arcs:
                if arc[0] == node:
                    outgoing.append(flow2[arc])

            if incoming and outgoing:
                solver2.Add(solver2.Sum(incoming) == solver2.Sum(outgoing))

        consumer_inflows = []
        for arc in arcs:
            if arc[1] == "consumer":
                consumer_inflows.append(flow2[arc])
        solver2.Add(total_power2 == solver2.Sum(consumer_inflows))

        cost_terms = []
        for arc in arcs:
            cost_terms.append(cost[arc] * flow2[arc])
        solver2.Add(total_cost2 == solver2.Sum(cost_terms))

        solver2.Add(total_power2 == max_power_value)

        solver2.Minimize(total_cost2)

        status2 = solver2.Solve()

        if status2 == pywraplp.Solver.OPTIMAL:
            final_max_power = total_power2.solution_value()
            final_total_cost = total_cost2.solution_value()

            node_to_index = {node: idx for idx, node in enumerate(nodes)}
            power_allocation = []
            for arc in arcs:
                power = flow2[arc].solution_value()
                if power > 1e-5:
                    from_idx = node_to_index[arc[0]]
                    to_idx = node_to_index[arc[1]]
                    power_allocation.append([from_idx, to_idx, round(power)])

            print(json.dumps({
                "max_power": round(final_max_power),
                "total_cost": round(final_total_cost),
                "power_allocation": power_allocation
            }))
        else:
            print(f"Solver status: {status2}")
    else:
        print(f"Solver status: {status}")

if __name__ == "__main__":
    main()
